EXPLANATION: Use safe session management or sanitized values to prevent cookie injection or header manipulation via unvalidated session tokens.
```python
@app.route("/login", methods=["POST"])
def login():
    username = request.form.get("username")
    password = request.form.get("password")
    remember_me = request.form.get("remember_me")

    if (
        username in users and users[username]["password"] == password
    ):  # Vulnerable: Plain text password comparison
        response = make_response(redirect(url_for("dashboard")))

        # Vulnerable: Insecure session management
        session_token = base64.b64encode(
            f"{username}:{datetime.now()}".encode()
        ).decode()
        safe_token = "".join(c for c in session_token if c.isalnum() or c in "-_")

        if remember_me:
            # Vulnerable: Insecure "Remember Me" implementation
            response.set_cookie("session", safe_token, max_age=30 * 24 * 60 * 60)
        else:
            response.set_cookie("session", safe_token)

        return response

    flash("Invalid username or password")
    return redirect(url_for("lab"))
```

